def step(self) -> dict[str, Any]:
    """Synchronous update of all cells."""
    old = self._grid
    new = np.zeros_like(old)
    wavefront = 0

    for r in range(self.rows):
        for c in range(self.cols):
            state = old[r, c]
            if state == 0:
                # Resting: check if enough neighbors are excited
                excited_neighbors = self._count_excited_neighbors(old, r, c)
                if excited_neighbors >= self.threshold:
                    new[r, c] = 1
                    wavefront += 1
                else:
                    new[r, c] = 0
            elif state == 1:
                # Excited → first refractory
                new[r, c] = 2
            else:
                # Refractory: advance, or return to resting
                new[r, c] = (state + 1) % self.n_states
                # Note: if n_states=3, state 2 → 0 (resting)

    self._grid = new
    self._wavefront_count = wavefront
    self._step_count += 1

    return self._snapshot()

def step(self) -> dict[str, Any]:
    """One round: activate all non-frozen cells in random order."""
    if self._converged:
        return self._snapshot()

    active_indices = np.where(~self._frozen)[0]
    self.rng.shuffle(active_indices)

    any_swap = False
    for i in active_indices:
        swapped = self._cell_action(int(i))
        if swapped:
            any_swap = True
            self._swap_count += 1

    self._step_count += 1

    if not any_swap and self._no_cell_should_move():
        self._converged = True

    return self._snapshot()

def adaptive_voter(seed: int = 0, N: int = 200, mean_deg: int = 4, phi: float = 0.99,
                   max_steps: int = 400000, n_frames: int = 80) -> Built:
    """Adaptive voter -> fragmentation transition (the evolving-network positive)."""
    rng = np.random.default_rng(seed)
    op = rng.integers(0, 2, N)
    p = mean_deg / (N - 1)
    A = (np.triu(rng.random((N, N)), 1) < p).astype(np.int8)
    A = A + A.T
    frames: List[Dict[str, Any]] = []
    snap = max(1, max_steps // n_frames)
    for step in range(max_steps):
        i = int(rng.integers(N))
        nbrs = np.nonzero(A[i])[0]
        if nbrs.size == 0:
            if step % snap == 0:
                frames.append({"adjacency": A.astype(float).copy(), "opinions": op.copy()})
            continue
        j = int(nbrs[rng.integers(nbrs.size)])
        if op[i] != op[j]:
            if rng.random() < phi:
                same = np.nonzero(op == op[i])[0]
                same = same[(same != i)]
                if same.size:
                    l = int(same[rng.integers(same.size)])
                    A[i, j] = A[j, i] = 0
                    A[i, l] = A[l, i] = 1
            else:
                op[i] = op[j]
        if step % snap == 0:
            frames.append({"adjacency": A.astype(float).copy(), "opinions": op.copy()})
    frames.append({"adjacency": A.astype(float).copy(), "opinions": op.copy()})
    return frames, {"model": "adaptive_voter", "phi": phi, "N": N, "mean_deg": mean_deg}
